// The proposed effects. Each: { id, name, group, dur (ms loop), note, draw(g, t) }.
// Every effect aims at ANCHORS (see U() in the engine): a unit's body centre (x, mid), the top of its
// body (top), its feet (y) and its front (x -/+ hw). No hand-picked pixel nudges.
const SP = {};
const WEAPON_LETTERS = { goblin: 'c', skeletonArcher: 'rt', bandit: 'g', orcBrute: 'c' };
function heroSprite(id) {
  // Same as assemble(), but remembers which letters belong to the weapon (not part of the body).
  const h = HEROES.find((x) => x.id === id);
  const s = assemble(h);
  const n = Object.keys(h.body.pal).length + Object.keys(h.head.pal).length; // codes are given body, head, weapon in order
  const codes = Object.keys(s.pal);
  const weapon = new Set(codes.slice(n));
  return prepSprite(s.pal, s.rows, false, (c) => !weapon.has(c));
}
function enemySprite(list, id) {
  const e = list.find((x) => x.id === id);
  const wl = WEAPON_LETTERS[id] || '';
  return prepSprite(e.pal, e.rows, true, (c) => !wl.includes(c));
}
function buildSprites() {
  SP.knight = heroSprite('knight'); SP.rogue = heroSprite('rogue'); SP.archer = heroSprite('archer');
  SP.goblin = enemySprite(OLD_ENEMIES, 'goblin'); const sk = ENEMIES.find((x) => x.id === 'skeletonArcher'); SP.skeleton = prepSprite(sk.pal, sk.rows.map((r) => r.replace(/[rt]/g, '.')), true); SP.slime = enemySprite(OLD_ENEMIES, 'slime'); SP.rat = enemySprite(ENEMIES, 'rat');
}

// ---- stages ----------------------------------------------------------------------------------------
const HX = 32, HY = 54, EX = 88, EY = 54;
// One hero (Knight) against one enemy (Goblin). Returns their anchors (with the offsets applied).
function solo(g, ho = {}, eo = {}) {
  const h = U(SP.knight, HX, HY, ho), e = U(SP.goblin, EX, EY, eo);
  g.shadow(HX, HY, 12); g.shadow(EX, EY, 12);
  if (!eo.hide) g.sprite(SP.goblin, EX, EY, eo);
  if (!ho.hide) g.sprite(SP.knight, HX, HY, ho);
  return { h, e };
}
const HEROS = [['archer', 16, 40], ['rogue', 36, 48], ['knight', 20, 58]];
const FOES = [['goblin', 86, 42], ['slime', 104, 50], ['rat', 84, 58]];
function squad(g, ho = [], eo = []) {
  const hs = HEROS.map(([n, x, y], i) => U(SP[n], x, y, ho[i] || {}));
  const es = FOES.map(([n, x, y], i) => U(SP[n], x, y, eo[i] || {}));
  for (const [, x, y] of [...HEROS, ...FOES]) g.shadow(x, y, 10);
  FOES.forEach(([n, x, y], i) => { const o = eo[i] || {}; if (!o.hide) g.sprite(SP[n], x, y, o); });
  HEROS.forEach(([n, x, y], i) => { const o = ho[i] || {}; if (!o.hide) g.sprite(SP[n], x, y, o); });
  return { hs, es };
}
// Static anchors (no offsets), for paths computed before drawing.
const H0 = () => U(SP.knight, HX, HY), E0 = () => U(SP.goblin, EX, EY);
const HS = (i) => U(SP[HEROS[i][0]], HEROS[i][1], HEROS[i][2]);
const FS = (i) => U(SP[FOES[i][0]], FOES[i][1], FOES[i][2]);
// Points on a unit: where a hit lands (its front, facing the attacker), where a shot leaves (hero's weapon side).
const front = (u, side = -1) => [u.x + side * u.hw, u.mid];
const muzzle = (u) => [u.x + u.hw + 2, u.mid - 1];
// Reactions
const hitReact = (t, at) => { const p = ph(t, at, at + 160); return p > 0 && p < 1 ? { flash: 1 - p, dx: Math.round(2 * (1 - p)) } : {}; };
const lunge = (t, at, dist = 6) => { const p = ph(t, at - 120, at + 140); return { dx: p > 0 && p < 1 ? Math.round(Math.sin(p * Math.PI) * dist) : 0 }; };
const shake = (t, a, b) => { const p = ph(t, a, b); return p > 0 && p < 1 ? (Math.floor(t / 30) % 2 ? 1 : -1) : 0; };
const num = (g, u, str, col, p, s = 1) => g.pop(str, u.x, u.top - 2, col, p, s);

const C = { fire: '#ff9a2e', fire2: '#ffe066', ice: '#9fe0ff', ice2: '#dff6ff', elec: '#ffe94d', dark: '#b07cff', dark2: '#5a2d8a', holy: '#fff2a0', holy2: '#f2c544', blood: '#d9452b', poison: '#6de07a', heal: '#6dff8f', shield: '#6fd0ff', grey: '#c8ccd6', gold: '#f2c544' };

// ---- freeze: ice that grows over the sprite's own shape ----------------------------------------------
// level 0..1 = how far up the body the ice has climbed; crack 0..1 = breaking apart.
function iceRecolor(sp, level) {
  const cut = sp.h - level * (sp.h + 2);
  return (c, px, py, out) => {
    if (py < cut) return c;
    if (out) return '#e8fbff'; // the outline becomes a bright rim of ice
    const [r, g, b] = hexRgb(c); const lum = (r * 0.3 + g * 0.59 + b * 0.11) / 255;
    return lum > 0.6 ? '#dff6ff' : lum > 0.35 ? '#9fe0ff' : '#5aaee0';
  };
}
// Crystals grow out of the outline at fixed spots (top, upper sides), pointing away from the body.
function crystals(g, sp, u, grow, alpha = 1) {
  const left = Math.round(u.x - sp.cx), top = Math.round(u.y - sp.h);
  const outs = sp.px.filter((p) => p[3]);
  const pick = (fn) => outs.reduce((a, b) => (fn(b) < fn(a) ? b : a));
  const spots = [pick((p) => p[1]), pick((p) => p[0] + p[1] * 0.6), pick((p) => -p[0] + p[1] * 0.6), pick((p) => p[0] + p[1] * 0.15), pick((p) => -p[0] + p[1] * 0.15)];
  spots.forEach(([px, py], i) => {
    const dx = px + 0.5 - sp.cx, dy = py - (sp.cTop + sp.cBot) / 2; const d = Math.hypot(dx, dy) || 1;
    const len = Math.round((i === 0 ? 4 : 3) * grow);
    for (let k = 1; k <= len; k++) { g.px(left + px + (dx / d) * k, top + py + (dy / d) * k, k === len ? '#ffffff' : '#bfefff', alpha); }
  });
}

// Four L-shaped corner brackets around a unit's body, pulled in/out by `pad`.
function brackets(g, u, pad, col, a = 1) {
  const x0 = Math.round(u.x - u.hw - pad), x1 = Math.round(u.x + u.hw + pad), y0 = Math.round(u.top - pad), y1 = Math.round(u.bot + pad);
  for (const [cx, cy, dx, dy] of [[x0, y0, 1, 1], [x1, y0, -1, 1], [x0, y1, 1, -1], [x1, y1, -1, -1]]) for (let k = 0; k < 3; k++) { g.px(cx + dx * k, cy, col, a); g.px(cx, cy + dy * k, col, a); }
}
// A small flame tuft at (x, y = its base), h tall, flickering with time t.
function flame(g, x, y, h, t, seed) {
  for (let j = 0; j < h; j++) { const w = j < h * 0.4 ? 1 : 0; const sway = Math.round(Math.sin(t / 90 + seed + j) * (j / h)); for (let k = -w; k <= w; k++) g.px(x + k + sway, y - j, j >= h - 1 ? '#ffffff' : j > h * 0.5 ? C.fire2 : C.fire, 0.95); }
}

// The same death everywhere: d = 0..1 over the death. White flash, squashed into the floor, gone.
function dying(d) { if (d <= 0) return {}; if (d >= 1) return { hide: true }; return { flash: d < 0.3 ? 1 : 0, squash: ease.in(d) * 0.9, alpha: 1 - d * 0.4 }; }
// Grey smoke puff where a unit died (q = 0..1).
function deathPuff(g, u, q) { if (q <= 0 || q >= 1) return; for (let i = 0; i < 5; i++) g.disc(u.x + (i - 2) * 3, u.y - 3 - q * (6 + (i % 3) * 3), 2 + (i % 2), '#8c909c', (1 - q) * 0.8); }
// A unit sprite rising out of the floor (r = 0..1): only the part above the floor shows.
function rise(g, sp, x, y, r, o = {}) { const left = Math.round(x - sp.cx), off = Math.round((1 - r) * sp.h); for (const [px, py, c] of sp.px) { const yy = y - sp.h + py + off; if (yy < y) g.px(left + px, yy, c, o.alpha ?? 1); } }

